def contains_iter(lst, target):
    for item in lst:
        if item == target:
            return True
    return False

print(contains_iter([], 5))

items.solution_code:
def contains_rec(lst, target):
    if not lst:
        return False
    if lst[0] == target:
        return True
    return contains_rec(lst[1:], target)

print(contains_iter([], 5))
print(contains_rec([], 5))

